create or replace function public.broadcast_new_listing(
  p_type text,  -- 'business' | 'provider' | 'place'
  p_id text
)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  r_user record;
  v_count int := 0;
  v_lat double precision;
  v_lng double precision;
  v_radius_km double precision := 5.0;
  v_owner_id text;
  v_name text;
  v_cat text;
  v_img text;
  v_addr text;
  v_phone text;
  v_notif_type text;
  v_title text;
  v_body text;
  v_link text;
  v_meta jsonb;
begin
  if p_type = 'business' then
    select owner_user_id, lat, lng, broadcast_radius, name, category_name, cover_image, address_line1, phone
      into v_owner_id, v_lat, v_lng, v_radius_km, v_name, v_cat, v_img, v_addr, v_phone
      from public.businesses
     where id = p_id;
    if not found then return 0; end if;

    v_radius_km := coalesce(v_radius_km, 5.0);
    v_cat := coalesce(v_cat, 'Shop');
    v_name := coalesce(v_name, 'A new business');
    v_notif_type := 'NEW_BUSINESS';
    v_title := 'New ' || v_cat || ' near you';
    v_body := v_name || ' is now open in your area';
    v_link := '/business/' || p_id;

    v_meta := jsonb_build_object(
      'businessId', p_id,
      'businessName', v_name,
      'category', v_cat,
      'imageUrl', v_img,
      'address', v_addr,
      'phone', v_phone,
      'lat', v_lat,
      'lng', v_lng,
      'statusPill', 'Newly Opened',
      'tone', 'primary',
      'actions', jsonb_build_array('VIEW_BUSINESS', 'DIRECTIONS')
    );

  elsif p_type = 'provider' then
    select user_id, lat, lng, service_radius_km, display_name, category_name, avatar, phone
      into v_owner_id, v_lat, v_lng, v_radius_km, v_name, v_cat, v_img, v_phone
      from public.providers
     where id = p_id;
    if not found then return 0; end if;

    v_radius_km := coalesce(v_radius_km, 5.0);
    v_cat := coalesce(v_cat, 'Provider');
    v_name := coalesce(v_name, 'A new provider');
    v_notif_type := 'NEW_PROVIDER';
    v_title := 'New ' || v_cat || ' near you';
    v_body := v_name || ' is now available for bookings';
    v_link := '/provider/' || p_id;

    v_meta := jsonb_build_object(
      'providerId', p_id,
      'providerName', v_name,
      'category', v_cat,
      'imageUrl', v_img,
      'phone', v_phone,
      'lat', v_lat,
      'lng', v_lng,
      'statusPill', 'New Provider',
      'tone', 'positive',
      'actions', jsonb_build_array('VIEW_PROVIDER', 'BOOK_APPOINTMENT')
    );

  elsif p_type = 'place' then
    select submitted_by_user_id, lat, lng, name, category, cover_image, address_line1
      into v_owner_id, v_lat, v_lng, v_name, v_cat, v_img, v_addr
      from public.places
     where id = p_id;
    if not found then return 0; end if;

    v_radius_km := 10.0;
    v_cat := coalesce(v_cat, 'Place');
    v_name := coalesce(v_name, 'A new place');
    v_notif_type := 'NEW_PLACE';
    v_title := 'New ' || v_cat || ' near you';
    v_body := v_name || ' was just added to your neighborhood map';
    v_link := '/place/' || p_id;

    v_meta := jsonb_build_object(
      'placeId', p_id,
      'placeName', v_name,
      'category', v_cat,
      'imageUrl', v_img,
      'address', v_addr,
      'lat', v_lat,
      'lng', v_lng,
      'statusPill', 'New Landmark',
      'tone', 'brand',
      'actions', jsonb_build_array('VIEW_PLACE', 'DIRECTIONS')
    );
  else
    return 0;
  end if;

  if v_lat is null or v_lng is null then
    return 0;
  end if;

  -- Broadcast to nearby users who opted into new business/place discovery
  for r_user in
    select u.id
      from public.users u
     where u.id <> coalesce(v_owner_id, '')
       and coalesce(u.notif_new_business, true) = true
       and u.lat is not null and u.lng is not null
       and u.lat between v_lat - (least(v_radius_km, 50.0) / 111.0) and v_lat + (least(v_radius_km, 50.0) / 111.0)
       and u.lng between v_lng - (least(v_radius_km, 50.0) / 111.0) and v_lng + (least(v_radius_km, 50.0) / 111.0)
     limit 250
  loop
    insert into public.notifications (
      user_id,
      type,
      title,
      body,
      deep_link,
      metadata,
      entity_type,
      entity_id
    ) values (
      r_user.id,
      v_notif_type,
      v_title,
      v_body,
      v_link,
      v_meta,
      upper(p_type),
      p_id
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;

create or replace function public.grant_team_access(
  p_business_id text,
  p_identifier text,
  p_scopes text[]
)
returns table (session_id uuid, grantee_name text)
language plpgsql security definer
set search_path = public
as $fn$
declare
  v_uid text := auth.uid()::text;
  v_target text;
  v_name text;
  v_biz_name text;
  v_scopes text[] := coalesce((select array_agg(distinct s) from unnest(p_scopes) as s
                                 where s in ('appointments','queue','catalog','leads','delivery')), '{}');
  v_session_id uuid;
  v_meta jsonb;
begin
  if v_uid is null then raise exception 'UNAUTHENTICATED'; end if;
  if not exists (select 1 from public.businesses where id = p_business_id and owner_user_id = v_uid) then
    raise exception 'NOT_ALLOWED';
  end if;

  select name into v_biz_name from public.businesses where id = p_business_id;

  select id, coalesce(name, alias, 'User')
    into v_target, v_name
    from public.users
   where lower(phone) = lower(p_identifier)
      or lower(alias) = lower(p_identifier)
      or id = p_identifier
   limit 1;

  if v_target is null then raise exception 'USER_NOT_FOUND'; end if;
  if v_target = v_uid then raise exception 'CANNOT_GRANT_TO_SELF'; end if;
  if array_length(v_scopes, 1) is null then raise exception 'Pick at least one section to grant access to.'; end if;

  select id into v_session_id
    from public.business_access_sessions
   where business_id = p_business_id and grantee_user_id = v_target;

  if v_session_id is not null then
    update public.business_access_sessions
       set status = 'ACTIVE', decided_at = now(), expires_at = null,
           access_level = 'SCOPED', scopes = v_scopes
     where id = v_session_id;
  else
    insert into public.business_access_sessions
      (business_id, grantee_user_id, status, decided_at, expires_at, access_level, scopes)
    values (p_business_id, v_target, 'ACTIVE', now(), null, 'SCOPED', v_scopes)
    returning id into v_session_id;
  end if;

  v_meta := jsonb_build_object(
    'businessId', p_business_id,
    'businessName', coalesce(v_biz_name, 'a business'),
    'scopes', v_scopes,
    'statusPill', 'Team Access',
    'tone', 'brand',
    'actions', jsonb_build_array('SWITCH_BUSINESS')
  );

  begin
    insert into public.notifications (
      user_id,
      type,
      title,
      body,
      deep_link,
      metadata,
      entity_type,
      entity_id
    ) values (
      v_target,
      'BUSINESS_ACCESS',
      'Team access granted',
      'You can now help manage ' || coalesce(v_biz_name, 'a business') || ' from Switch account.',
      '/account/business-access',
      v_meta,
      'BUSINESS',
      p_business_id
    );
  exception when others then null; end;

  session_id := v_session_id;
  grantee_name := coalesce(v_name, 'User');
  return next;
end $fn$;

